// Test setup with Testcontainers
const kafka = new KafkaContainer().withExposedPorts(9093);
const testTopics = ['tenant-1-trades', 'tenant-2-trades'];

// Deterministic data seeding
const seedTrades = () => {
  return Array.from({length: 1000}, (_, i) => ({
    id: `trade-${i}`,
    timestamp: Date.now() - (i * 60),
    symbol: 'AAPL',
    price: 150 + (i % 10),
    quantity: 100
  }));
};

// Event replay simulation
const replayEvents = (events, delay) => {
  events.forEach(event => {
    setTimeout(() => producer.send(event), delay);
  });
};

// UI verification with Playwright
const verifyDashboard = async (page, expectedAggregates) => {
  await page.waitForSelector('[data-testid="dashboard"]');
  const aggregates = await page.evaluate(() => {
    return window.dashboard.getAggregates();
  });
  expect(aggregates).toEqual(expectedAggregates);
};
```

